local function bestRun(dungeon)if type(dungeon)~="table"then return nil end;if type(dungeon.bestRun)=="table"then return dungeon.bestRun end;local best;local function consider(entry,overTime)if type(entry)~="table"then return end;local score=tonumber(entry.dungeonScore or entry.score or entry.seasonScore);local level=tonumber(entry.level or entry.bestLevel);if level and level>0 and(not best or(score or 0)>(best.score or 0)or((score or 0)==(best.score or 0)and level>(best.level or 0)))then best={level=level,score=score or 0,durationSec=tonumber(entry.durationSec),overTime=overTime==true or entry.overTime==true}end end;consider(dungeon.bestInTime,false);consider(dungeon.bestOverTime,true);for _,entry in pairs(type(dungeon.affixScores)=="table"and dungeon.affixScores or{})do consider(entry,type(entry)=="table"and entry.overTime)end;return best end
