"BEST_KEY"].."\n|cffffffff"..value(bestLevel).."|r",L["OVERALL_RATING"].."\n|cffffd100"..number(snapshot.overallScore).."|r"},columns=summaryColumns,style="summary",maxWidth=1320};C:SetView(view,L["DISPLAY_NAME"],lines,status,meta,{[1]="accent"})end
